CREATE TABLE rescue_points(id BIGSERIAL PRIMARY KEY,name VARCHAR(255) NOT NULL,province VARCHAR(100) NOT NULL,district VARCHAR(100),ward VARCHAR(100),address_detail TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE rescue_registrations(id BIGSERIAL PRIMARY KEY,crop_batch_id BIGINT NOT NULL,farmer_id BIGINT NOT NULL,rescue_point_id BIGINT NOT NULL REFERENCES rescue_points(id),admin_id BIGINT,crop_name_snapshot VARCHAR(100),quantity_snapshot NUMERIC(12,2),status VARCHAR(20) NOT NULL DEFAULT 'PENDING',submitted_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE rescue_status_history(id BIGSERIAL PRIMARY KEY,registration_id BIGINT NOT NULL REFERENCES rescue_registrations(id),from_status VARCHAR(20),to_status VARCHAR(20) NOT NULL,changed_by BIGINT,changed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox_events(id UUID PRIMARY KEY,aggregate_type VARCHAR(100) NOT NULL,aggregate_id VARCHAR(100) NOT NULL,event_type VARCHAR(100) NOT NULL,event_version INTEGER NOT NULL,payload JSONB NOT NULL,status VARCHAR(30) NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published_at TIMESTAMP WITH TIME ZONE,last_error TEXT);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_rescue_farmer ON rescue_registrations(farmer_id); CREATE INDEX idx_rescue_status ON rescue_registrations(status);
